{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic does not specify a customer-managed encryption key (CMEK) in the kms_key_name attribute, relying on Google-managed keys by default. This violates the requirement to use Customer Supplied Encryption Keys for sensitive data."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n\n  # Note: In a real environment, replace this with a valid KMS Key ID or reference.\n  # Since no variable was provided, we add the structure required for CSEK compliance.\n  # If a specific key is not available, this field must be populated to pass CKV_GCP_83.\n  # For the purpose of this patch demonstrating the fix structure:\n  kms_key_name = \"projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to the `google_pubsub_topic` resource to enable Customer Managed Encryption Keys (CMEK), addressing check CKV_GCP_83. A placeholder KMS key path was used as none was provided in the original file; this should be replaced with an actual KMS key ARN/ID in production."
}
